"""Artifact bundle helpers shared by notebooks 02 and 03: model card text, sha256sums, bundle metrics skeleton."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

CARD = """# {title}

**Training data: synthetic only.** Every training and development example was generated by code (`ml/train`): an LLM
({generator}) wrote document templates with typed slots, and Python filled the slots with generated values and recorded
the labels. No real person's data was used. **Not validated on real data.** Metrics below are measured on a synthetic
development split (split by template) and are optimistic; real-world recall is unknown until it is measured on
human-labelled, consented, in-boundary tickets.

## Intended use
{intended}

## Not intended for
Being the only control protecting personal data; as a substitute for human-labelled evaluation on real tickets;
processing text in non-Latin scripts (training covered Latin-script Indian English, Hinglish and code-mixed text).

## Base model
{base} (licence: {licence}). Fine-tuned in fp16, exported to ONNX, dynamic int8 quantisation (per-channel).

## Labels
{labels}

## Metrics (synthetic dev split)
```json
{metrics}
```

## Known limitations
Synthetic text is cleaner and more regular than real tickets. Rare formats, heavy OCR noise and non-Latin scripts are
under-represented. Over-masking is preferred to leaking, so precision is lower than recall by design.
"""


def write_card(path, title: str, generator: str, intended: str, base: str, licence: str, labels, metrics: dict) -> None:
    Path(path).write_text(CARD.format(title=title, generator=generator, intended=intended, base=base, licence=licence,
                                      labels=", ".join(labels), metrics=json.dumps(metrics, indent=2, sort_keys=True)[:6000]),
                          encoding="utf-8")


def write_sha256sums(directory) -> dict[str, str]:
    d = Path(directory)
    sums = {}
    for f in sorted(d.iterdir()):
        if f.is_file() and f.name != "sha256sums":
            h = hashlib.sha256()
            with open(f, "rb") as fh:
                for chunk in iter(lambda: fh.read(1 << 20), b""):
                    h.update(chunk)
            sums[f.name] = h.hexdigest()
    (d / "sha256sums").write_text("".join(f"{v}  {k}\n" for k, v in sums.items()), encoding="utf-8")
    return sums


def max_recall_drop(fp32: dict, int8: dict, min_support: int = 30) -> float:
    """fp32/int8: {"micro": recall, "per_type": {name: (recall, support)}}. Largest recall loss (points as a fraction)."""
    drops = [fp32["micro"] - int8["micro"]]
    for k, (r, sup) in fp32["per_type"].items():
        if sup >= min_support and k in int8["per_type"]:
            drops.append(r - int8["per_type"][k][0])
    return round(max(drops), 4)
